    assessmentTools: { rubric: ['Habit vs one event', 'Reason from the text', 'used to / bigger than / told … not to', 'Personal sentences'], exitTicket: ['Write one “When I was small, I used to …” sentence and one “My mother told me not to …” sentence.'] },
